class Solution {
    public int alternatingSubarray(int[] nums) {
        int best = -1;
        for (int start = 0; start < nums.length - 1; start++) {
            int expected = 1;
            for (int end = start + 1; end < nums.length; end++) {
                if (nums[end] - nums[end - 1] != expected) {
                    break;
                }
                best = Math.max(best, end - start + 1);
                expected *= -1;
            }
        }
        return best;
    }
}

class Solution {
    public int alternatingSubarray(int[] nums) {
        int best = -1;
        int start = 0;
        int expected = 1;
        for (int i = 1; i < nums.length; i++) {
            int diff = nums[i] - nums[i - 1];
            if (diff == expected) {
                best = Math.max(best, i - start + 1);
                expected *= -1;
            } else if (diff == 1) {
                start = i - 1;
                best = Math.max(best, 2);
                expected = -1;
            } else {
                start = i;
                expected = 1;
            }
        }
        return best;
    }
}

class Solution {
    public int alternatingSubarray(int[] nums) {
        int best = -1;
        int length = 1;
        for (int i = 1; i < nums.length; i++) {
            int diff = nums[i] - nums[i - 1];
            if (length == 1) {
                length = diff == 1 ? 2 : 1;
            } else {
                int expected = length % 2 == 0 ? -1 : 1;
                if (diff == expected) {
                    length++;
                } else {
                    length = diff == 1 ? 2 : 1;
                }
            }
            if (length >= 2) {
                best = Math.max(best, length);
            }
        }
        return best;
    }
}
